"""
    Checks if all keys of the configuration "structure" are defined in the "agents" section
    :param configuration: the object group to look at
    :return: if all agents are well defined
    """
def check_agents_are_known(configuration: Any) -> object {
    known_agents = configuration["agents"];
    known_agents_id = [agent["id"] for agent in known_agents];
    agents_list = configuration["structure"].keys();
    for agent in agents_list {
        if (agent not in known_agents_id) {
            return False;
        }
    }
    return True;
}

test_blocks:
test "t0" {
    assert (
        check_agents_are_known({"agents": [], "structure": {"a": {"b": 1}}}) == False
    );;
}

test "t1" {
    assert (
        check_agents_are_known(
            {
                "agents": [
                    {"id": "agent_1", "x": 1, "y": 2},
                    {"id": "agent_2", "x": 3, "y": 4}
                ],
                "structure": {
                    "agent_1": {"state": "a", "next_state": "b", "probability": 0.5},
                    "agent_3": {"state": "a", "next_state": "b", "probability": 0.5}
                }
            }
        )
        == False
    );;
}

test "t2" {
    assert (
        check_agents_are_known(
            {
                "agents": [
                    {"id": "a", "class": "X"},
                    {"id": "b", "class": "X"},
                    {"id": "c", "class": "Y"},
                    {"id": "d", "class": "Y"}
                ],
                "structure": {
                    "a": [
                        {"agent": "b", "relation": "parent"},
                        {"agent": "c", "relation": "parent"}
                    ],
                    "b": [],
                    "c": [],
                    "d": []
                }
            }
        )
        == True
    );;
}

test "t3" {
    assert (
        check_agents_are_known(
            {
                "agents": [{"id": "test_agent"}],
                "structure": {
                    "test_agent": {"policy_name": "test_policy", "name": "Test Agent"}
                }
            }
        )
        == True
    );;
}

test "t4" {
    assert (
        check_agents_are_known(
            {
                "agents": [
                    {"id": 0, "position": {"x": 0, "y": 0}, "orientation": "N"},
                    {"id": 1, "position": {"x": 0, "y": 1}, "orientation": "S"},
                    {"id": 2, "position": {"x": 0, "y": 2}, "orientation": "E"},
                    {"id": 3, "position": {"x": 0, "y": 3}, "orientation": "W"}
                ],
                "structure": {0: [1, 2, 3]}
            }
        )
        == True
    ) , "Expected True";;
}

test "t5" {
    assert (
        check_agents_are_known(
            {
                "agents": [
                    {"id": "agent_1", "x": 1, "y": 2},
                    {"id": "agent_2", "x": 3, "y": 4}
                ],
                "structure": {
                    "agent_1": {"state": "a", "next_state": "b", "probability": 0.5},
                    "agent_2": {"state": "a", "next_state": "b", "probability": 0.5}
                }
            }
        )
        == True
    );;
}

test "t6" {
    assert (
        check_agents_are_known(
            {
                "agents": [],
                "structure": {
                    "test_agent": {"policy_name": "test_policy", "name": "Test Agent"}
                }
            }
        )
        == False
    );;
}

test "t7" {
    assert (
        check_agents_are_known(
            {
                "agents": [{"id": "agent_id", "color": "red"}],
                "structure": {
                    "another_agent_id": {
                        "id": "first_agent_id",
